1316		// 由逐件轨迹校验核对），成员必须非空、不重复、均属原单且按发运保存顺序排列；
1317		// 同一运输单各次接收的成员不得重叠（同单同件只能接收一次）；每件成员的轨迹中
1318		// 都有与该接收请求一致的接收记录。关联缺失、同单同件重复接收或与轨迹矛盾即损坏。
1319		receiveSeen := make(map[string]map[string]string) // 运输单号 -> 包裹 -> 接收请求号
1320		for req, r := range l.Receives {
1321			if r == nil || req != r.Request || r.Shipment == "" || r.Station == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
1322				return fmt.Errorf("%w: 接收请求号 %q 的接收结果不完整", ErrCorrupt, req)
1323			}
1324			sh, ok := l.Shipments[r.Shipment]
1325			if !ok || sh == nil {
