1327			}
1328			member := make(map[string]bool, len(sh.Parcels))
1329			for _, pid := range sh.Parcels {
1330				member[pid] = true
1331			}
1332			seen := make(map[string]bool, len(r.Parcels))
1333			pos := 0 // 成员必须按发运保存顺序排列：在 sh.Parcels 中的位置严格递增
