1344					if sh.Parcels[i] == pid {
1345						at = i
1346						break
1347					}
1348				}
1349				if at < 0 {
1350					return fmt.Errorf("%w: 接收请求号 %q 的成员顺序与运输单 %q 的发运保存顺序不一致", ErrCorrupt, req, r.Shipment)
1351				}
1352				pos = at + 1
1353				if prev, dup := receiveSeen[r.Shipment][pid]; dup {
1354					return fmt.Errorf("%w: 包裹 %q 在运输单 %q 下被接收请求 %q 与 %q 重复接收，同单同件只能接收一次",
1355						ErrCorrupt, pid, r.Shipment, prev, req)
1356				}
1357				if receiveSeen[r.Shipment] == nil {
1358					receiveSeen[r.Shipment] = make(map[string]string)
1359				}
1360				receiveSeen[r.Shipment][pid] = req
1361			}
1362			for _, pid := range r.Parcels {
1363				p, ok := l.Parcels[pid]
1364				if !ok {
1365					return fmt.Errorf("%w: 接收请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
1366				}
1367				found := false
1368				for _, e := range p.Trail {
1369					if e.Op == "接收" && e.Request == req {
1370						found = true
1371						break
1372					}
1373				}
1374				if !found {
1375					return fmt.Errorf("%w: 接收请求号 %q 的成员包裹 %q 缺少对应的接收轨迹", ErrCorrupt, req, pid)
