1380		// 前目的站与源站；运输单的改址列表必须按保存顺序恰含该请求一次（链式衔接
1381		// 由运输单校验核对）；集合非空、不重复、均属原单且按发运保存顺序排列；
1382		// 每件成员的轨迹中都有与该改址请求一致的改址记录。关联为空、缺失或矛盾即损坏。
1383		for req, r := range l.Reroutes {
1384			if r == nil || req != r.Request || r.Shipment == "" || r.From == "" || r.To == "" ||
1385				r.From == r.To || r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
