1391			}
1392			if r.To == sh.From {
1393				return fmt.Errorf("%w: 改址请求号 %q 的新目的站 %q 与运输单 %q 源站相同", ErrCorrupt, req, r.To, r.Shipment)
1394			}
1395			linked := 0
1396			for _, q := range sh.Reroutes {
1397				if q == req {
1398					linked++
1399				}
1400			}
1401			if linked != 1 {
1402				return fmt.Errorf("%w: 改址请求号 %q 与运输单 %q 的改址列表关联缺失或重复（出现 %d 次）", ErrCorrupt, req, r.Shipment, linked)
