1408			seen := make(map[string]bool, len(r.Parcels))
1409			pos := 0 // 集合必须按发运保存顺序排列：在 sh.Parcels 中的位置严格递增
1410			for _, pid := range r.Parcels {
1411				if !member[pid] {
1412					return fmt.Errorf("%w: 改址请求号 %q 的包裹 %q 不属于运输单 %q", ErrCorrupt, req, pid, r.Shipment)
