1428				pos = at + 1
1429			}
1430			for _, pid := range r.Parcels {
1431				p, ok := l.Parcels[pid]
1432				if !ok {
1433					return fmt.Errorf("%w: 改址请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
1434				}
1435				found := false
1436				for _, e := range p.Trail {
1437					if e.Op == "改址" && e.Request == req {
1438						found = true
1439						break
1440					}
1441				}
1442				if !found {
1443					return fmt.Errorf("%w: 改址请求号 %q 的成员包裹 %q 缺少对应的改址轨迹", ErrCorrupt, req, pid)
1444				}
1445			}
