1447		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
1448		// 再核对两张结果表与包裹当前状态的对应关系。
1449		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
1450		for id, p := range l.Parcels {
