1874	// Receipt 提交一件包裹在某个配送批次下的回执。
1875	//
1876	// 首次回执：批次必须存在，包裹必须属于该批次、在该批次没有未撤销的回执，且当前仍在该批次
1877	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
1878	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
1879	// 原因（失败时）、请求号和时间的回执记录；全部成员均有未撤销回执后批次自动完成。
1880	// 已撤销的回执不再占用该件的回执名额，可用新请求号重新回执（见 RevokeReceipt）。
1881	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
1882	// true，不重新检查当前状态，即使失败包裹已进入新批次或该回执已被撤销（重放不恢复回执，
1883	// 结果中可辨认已撤销）；请求号相同但内容不同报冲突。
1884	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
1885	// 失败的首次回执不占用请求号。
1886	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
1887		res, replayed, undo, err := s.applyReceipt(request, batch, parcel, result, reason, now)
1888		if err != nil || replayed {
1889			return res, replayed, err
1890		}
1891		if err := s.save(); err != nil {
1892			undo() // 落盘失败：回滚内存变更，保留原有有效数据
1893			return nil, false, err
1894		}
1895		return res, false, nil
1896	}
