1898	// applyReceipt 在内存台账上校验并应用一条回执（不落盘），是 Receipt 与
1899	// ImportReceipts 共用的核心。全部校验通过后才会改动数据；返回的 undo 可在
1900	// 整体保存失败时撤销本次改动（重放或校验失败时 undo 为 nil）。
1901	func (s *Store) applyReceipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, undo func(), err error) {
1902		if saved, ok := s.data.Receipts[request]; ok {
1903			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
1904				return saved, true, nil, nil
1905			}
1906			return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
1907				request, saved.Batch, saved.Parcel, saved.Result)
1908		}
1909	
1910		b, ok := s.data.Batches[batch]
1911		if !ok {
1912			return nil, false, nil, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
1913		}
1914		member := false
1915		for _, id := range b.Parcels {
1916			if id == parcel {
1917				member = true
1918				break
1919			}
1920		}
1921		if !member {
1922			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
1923		}
1924		if e, done := b.Receipts[parcel]; done && e.RevokedBy == "" {
1925			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能有一条未撤销回执", parcel, batch)
1926		}
1927		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
1928		if p.Status != statusDelivering || currentBatch(p) != batch {
1929			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
1930		}
1931	
1932		res = &ReceiptResult{
1933			Request: request,
1934			Batch:   batch,
1935			Parcel:  parcel,
1936			Result:  result,
1937			Reason:  reason,
1938			Time:    now,
1939		}
1940		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
1941	
1942		// 记录旧值，undo 在整体落盘失败时回滚。
1943		oldStatus, oldStation := p.Status, p.Station
1944		oldTrailLen := len(p.Trail)
1945		oldEntry, hadEntry := b.Receipts[parcel] // 被取代的已撤销条目（若有）
1946	
1947		if result == resultSigned {
1948			p.Status = statusSigned // 站点保留不变
1949		} else {
1950			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
1951			p.Station = b.Station
1952		}
1953		p.Trail = append(p.Trail, Event{
1954			Op:      "回执",
1955			Station: p.Station,
1956			Batch:   batch,
1957			Result:  result,
1958			Reason:  reason,
1959			Request: request,
1960			Time:    now,
1961		})
1962		b.Receipts[parcel] = entry
1963		s.data.Receipts[request] = res
1964	
1965		undo = func() {
1966			delete(s.data.Receipts, request)
1967			if hadEntry {
1968				b.Receipts[parcel] = oldEntry
1969			} else {
1970				delete(b.Receipts, parcel)
1971			}
1972			p.Status, p.Station = oldStatus, oldStation
1973			p.Trail = p.Trail[:oldTrailLen]
1974		}
1975		return res, false, undo, nil
1976	}
