1995	// ImportReceipts 按文件顺序整批应用回执记录。
1996	//
1997	// 逐条处理：与逐件 Receipt 共用同一回执请求号去重范围，同请求号且批次、包裹、
1998	// 结果、清理后的原因相同的记录返回首次结果与时间（重放），不检查当前状态、不追加
1999	// 轨迹、不改变批次进度；换内容报冲突。首次回执要求批次存在、包裹属于该批次、
2000	// 尚未在该批次回执且当前仍在该批次配送中（含本文件前面记录已产生的回执）。
2001	// 全部记录可接受时作为一个整体原子落盘；任一记录无效、冲突或受理条件不符，
2002	// 整份拒绝并提示记录位置，台账保持导入前状态，新请求号均不占用。
2003	// 全部为历史重放时不改写台账。
2004	func (s *Store) ImportReceipts(records []ReceiptImportRecord, now time.Time) ([]ReceiptImportItem, error) {
2005		// 在台账副本上按文件顺序试算：任一记录失败直接放弃副本，原台账保持不变。
2006		work, err := s.fork()
2007		if err != nil {
2008			return nil, err
2009		}
2010		items := make([]ReceiptImportItem, 0, len(records))
2011		hasNew := false
2012		for i, rec := range records {
2013			res, replayed, _, err := work.applyReceipt(rec.Request, rec.Batch, rec.Parcel, rec.Result, rec.Reason, now)
2014			if err != nil {
2015				return nil, fmt.Errorf("第 %d 条记录（请求号 %q）：%w", i+1, rec.Request, err)
2016			}
2017			if !replayed {
2018				hasNew = true
2019			}
2020			items = append(items, ReceiptImportItem{Record: rec, Time: res.Time, Replayed: replayed, Revoked: res.RevokedBy != ""})
2021		}
2022		if !hasNew {
2023			return items, nil // 全部为历史重放：不改写台账
2024		}
2025	
2026		// 整体提交：副本替换当前台账后一次原子落盘，失败时恢复导入前状态。
2027		orig := s.data
2028		s.data = work.data
2029		if err := s.save(); err != nil {
2030			s.data = orig
2031			return nil, err
2032		}
2033		return items, nil
2034	}
