2036	// fork 返回当前台账的深拷贝副本，供整批导入试算；副本上的任何改动都不影响原台账。
2037	func (s *Store) fork() (*Store, error) {
2038		buf, err := json.Marshal(s.data)
2039		if err != nil {
2040			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
2041		}
2042		var cp ledgerFile
2043		if err := json.Unmarshal(buf, &cp); err != nil {
2044			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
2045		}
2046		return &Store{path: s.path, data: cp}, nil
2047	}
