2049	// RevokeReceipt 撤销一条误录的配送回执：经核实包裹实际仍由原配送员配送，
2050	// 撤销错误的签收或失败登记，不收回实物。包裹与批次取自原回执，不可另选。
2051	//
2052	// 首次撤销：原回执必须存在、未撤销且仍为该件在该批次的有效回执；所属批次
2053	// 未中止、未转交；原回执必须是该包裹最后一条轨迹（其后发生过流转、冻结或
2054	// 解除均拒绝，其他成员的后续操作不阻止撤销），包裹仍在原出发站且状态与回执
2055	// 结果一致。任一不满足则拒绝，不作任何改动。成功后该件恢复原批次配送中，
2056	// 站点、配送员不变，该回执不再计入有效回执（原本已完成的批次恢复配送中，
2057	// 原成员顺序与出站或接手时间保留，其他成员及回执不变）；原回执结果与轨迹
2058	// 永久保留并标记已撤销，追加一条撤销回执记录，回执请求号不删除也不释放。
2059	// 每件同批次最多一条未撤销回执，撤销后可用新回执请求号再次提交签收或失败，
2060	// 也可随原批次中止或续接。撤销不恢复配送前旧交接的退回资格。
2061	// 撤销请求号独立去重，可与其他业务编号同名：相同请求号且原回执、清理后的
2062	// 原因相同，直接返回首次撤销信息和时间，replayed 为 true，不检查现状、不
2063	// 再次改变进度或改写台账（后续重新回执、中止或续接后仍成立）；请求号相同
2064	// 但内容不同报冲突。每条原回执只能撤销一次，换撤销号再次撤销它拒绝；
2065	// 失败的首次撤销不占用请求号。
2066	func (s *Store) RevokeReceipt(request, receiptReq, reason string, now time.Time) (res *RevokeResult, replayed bool, err error) {
2067		if saved, ok := s.data.Revokes[request]; ok {
2068			if saved.Receipt == receiptReq && saved.Reason == reason {
2069				return saved, true, nil
2070			}
2071			return nil, false, fmt.Errorf("撤销请求号 %q 已用于一次不同的撤销（原回执=%q 原因=%q），内容冲突",
2072				request, saved.Receipt, saved.Reason)
2073		}
2074	
2075		rc, ok := s.data.Receipts[receiptReq]
2076		if !ok {
2077			return nil, false, fmt.Errorf("撤销失败：原回执请求号 %q 不存在", receiptReq)
2078		}
2079		if rc.RevokedBy != "" {
2080			return nil, false, fmt.Errorf("撤销失败：原回执 %q 已撤销（撤销请求号 %q），每条原回执只能撤销一次", receiptReq, rc.RevokedBy)
2081		}
2082		if rc.ReturnedBy != "" {
2083			return nil, false, fmt.Errorf("撤销失败：原签收 %q 已办理实物退件（退件请求号 %q），退件后不能再撤销该签收", receiptReq, rc.ReturnedBy)
2084		}
2085		b := s.data.Batches[rc.Batch] // 回执所属批次必存在（载入校验保证）
2086		if b.AbortedBy != "" {
2087			return nil, false, fmt.Errorf("撤销失败：批次 %q 已中止（中止请求号 %q），不能撤销其中的回执", rc.Batch, b.AbortedBy)
2088		}
2089		if b.TransferredBy != "" {
2090			return nil, false, fmt.Errorf("撤销失败：批次 %q 已转交（续接请求号 %q），不能撤销其中的回执", rc.Batch, b.TransferredBy)
2091		}
2092		entry := b.Receipts[rc.Parcel]
2093		if entry == nil || entry.Request != receiptReq {
2094			return nil, false, fmt.Errorf("撤销失败：回执 %q 已不是包裹 %q 在批次 %q 的有效回执", receiptReq, rc.Parcel, rc.Batch)
2095		}
2096		p := s.data.Parcels[rc.Parcel] // 批次成员必已登记（载入校验保证）
2097		last := p.Trail[len(p.Trail)-1]
2098		if last.Op != "回执" || last.Request != receiptReq {
2099			return nil, false, fmt.Errorf("撤销失败：包裹 %q 在原回执 %q 之后又发生流转、冻结或解除，不能撤销该回执", rc.Parcel, receiptReq)
2100		}
2101		if p.Station != b.Station {
2102			return nil, false, fmt.Errorf("撤销失败：包裹 %q 当前归属 %q，不在原出发站 %q，不能撤销该回执", rc.Parcel, p.Station, b.Station)
2103		}
2104		want := statusSigned
2105		if rc.Result == resultFailed {
2106			want = statusInStation
2107		}
2108		if p.Status != want {
2109			return nil, false, fmt.Errorf("撤销失败：包裹 %q 当前状态为 %q，与原回执 %q 的结果 %q 不一致，不能撤销",
2110				rc.Parcel, p.Status, receiptReq, rc.Result)
2111		}
2112	
2113		res = &RevokeResult{
2114			Request: request,
2115			Receipt: receiptReq,
2116			Batch:   rc.Batch,
2117			Parcel:  rc.Parcel,
2118			Reason:  reason,
2119			Time:    now,
2120		}
2121		s.data.Revokes[request] = res
2122		rc.RevokedBy = request
2123		entry.RevokedBy = request
2124	
2125		// 记录旧值，落盘失败时整体回滚。
2126		oldStatus := p.Status
2127		oldTrailLen := len(p.Trail)
2128		p.Status = statusDelivering // 恢复原批次配送中，站点与配送员不变
2129		p.Trail = append(p.Trail, Event{
2130			Op:         "撤销回执",
2131			Station:    b.Station,
2132			Batch:      rc.Batch,
2133			Request:    request,
2134			RefRequest: receiptReq,
2135			Reason:     reason,
2136			Time:       now,
2137		})
2138	
2139		if err := s.save(); err != nil {
2140			delete(s.data.Revokes, request)
2141			rc.RevokedBy = ""
2142			entry.RevokedBy = ""
2143			p.Status = oldStatus
2144			p.Trail = p.Trail[:oldTrailLen]
2145			return nil, false, err
2146		}
2147		return res, false, nil
2148	}
