2150	// ReceiptReturn 办理签收后的实物退件：已真实签收的包裹实物送回该次配送的出发站。
2151	// 包裹、批次与接收站取自原回执及其批次，不允许另选。
2152	//
2153	// 首次退件：原回执必须存在、为未撤销的有效签收，且尚未办理过退件；包裹必须仍在
2154	// 原出发站归属下、状态为已签收，且最后一条轨迹就是该原回执。任一不符则拒绝，不作
2155	// 任何改动。原批次已完成、中止或转交，以及其他成员的后续作业，均不阻止满足条件的
2156	// 退件。成功后该件恢复原出发站“在站”，追加一条退件轨迹；原签收事实永久保留、仍计
2157	// 有效回执，原批次状态与进度不因退件改变，不恢复旧批次配送，也不能再撤销该签收。
2158	// 退件算新流转，不恢复旧交接的退回资格；之后该件可交接、冻结、发运或加入新配送批次。
2159	// 退件请求号独立去重，可与其他业务编号同名：相同请求号且原签收、清理后的原因相同，
2160	// 直接返回首次结果与时间，replayed 为 true，不检查现状、不追加轨迹或改写文件（后续
2161	// 流转及再次退件后仍成立）；请求号相同但内容不同报冲突。每条签收只能成功退件一次，
2162	// 换请求号再退拒绝；退件与撤销竞争至多一方成功；失败的首次退件不占用请求号。
2163	func (s *Store) ReceiptReturn(request, receiptReq, reason string, now time.Time) (res *ReceiptReturnResult, replayed bool, err error) {
2164		if saved, ok := s.data.ReceiptReturns[request]; ok {
2165			if saved.Receipt == receiptReq && saved.Reason == reason {
2166				return saved, true, nil
2167			}
2168			return nil, false, fmt.Errorf("退件请求号 %q 已用于一次不同的退件（原签收=%q 原因=%q），内容冲突",
2169				request, saved.Receipt, saved.Reason)
2170		}
2171	
2172		rc, ok := s.data.Receipts[receiptReq]
2173		if !ok {
2174			return nil, false, fmt.Errorf("退件失败：原签收回执请求号 %q 不存在", receiptReq)
2175		}
2176		if rc.Result != resultSigned {
2177			return nil, false, fmt.Errorf("退件失败：原回执 %q 的结果为 %q，只有已真实签收的包裹可以退件", receiptReq, rc.Result)
2178		}
2179		if rc.RevokedBy != "" {
2180			return nil, false, fmt.Errorf("退件失败：原签收 %q 已撤销（撤销请求号 %q），不能退件", receiptReq, rc.RevokedBy)
2181		}
2182		if rc.ReturnedBy != "" {
2183			return nil, false, fmt.Errorf("退件失败：原签收 %q 已成功退件（退件请求号 %q），每条签收只能退件一次", receiptReq, rc.ReturnedBy)
2184		}
2185		b := s.data.Batches[rc.Batch] // 回执所属批次必存在（载入校验保证）
2186		entry := b.Receipts[rc.Parcel]
2187		if entry == nil || entry.Request != receiptReq {
2188			return nil, false, fmt.Errorf("退件失败：签收 %q 已不是包裹 %q 在批次 %q 的有效回执", receiptReq, rc.Parcel, rc.Batch)
2189		}
2190		p := s.data.Parcels[rc.Parcel] // 批次成员必已登记（载入校验保证）
2191		if p.Station != b.Station {
2192			return nil, false, fmt.Errorf("退件失败：包裹 %q 当前归属 %q，不在原出发站 %q，不能退件", rc.Parcel, p.Station, b.Station)
2193		}
