2683	// BatchTransferSource 返回永久关闭该批次为“已转交”的最后一次续接结果；
2684	// 批次不存在或仍开放（尚未永久转交）时返回 nil。
2685	func (s *Store) BatchTransferSource(batch string) *TransferResult {
2686		b, ok := s.data.Batches[batch]
2687		if !ok || b.TransferredBy == "" {
2688			return nil
2689		}
2690		return s.data.Transfers[b.TransferredBy]
2691	}
