2693	// BatchTransfers 按提交顺序返回以该批次为原批次的各次续接结果；
2694	// 批次不存在或从未续接时为空。分批续接时可能含多条，最后一条未必永久关闭原批次。
2695	func (s *Store) BatchTransfers(batch string) []*TransferResult {
2696		b, ok := s.data.Batches[batch]
2697		if !ok {
2698			return nil
2699		}
2700		out := make([]*TransferResult, 0, len(b.Transfers))
2701		for _, req := range b.Transfers {
2702			if t := s.data.Transfers[req]; t != nil {
2703				out = append(out, t)
2704			}
2705		}
2706		return out
2707	}
