2709	// transferOfParcel 返回某成员在指定批次下被转交的续接结果；该件未从该批次转交时为 nil。
2710	func (s *Store) transferOfParcel(batch, pid string) *TransferResult {
2711		b, ok := s.data.Batches[batch]
2712		if !ok {
2713			return nil
2714		}
2715		for _, req := range b.Transfers {
2716			t := s.data.Transfers[req]
2717			if t == nil {
2718				continue
2719			}
2720			for _, id := range t.Parcels {
2721				if id == pid {
2722					return t
2723				}
2724			}
2725		}
2726		return nil
2727	}
