2734	// Ship 提交一次站间发运：整单包裹离开源站、尚未到达目的站。
2735	//
2736	// 首次发运：每件包裹必须已登记、当前归属源站且状态为在站；任一不满足则整单拒绝，
2737	// 不作任何改动（在途、配送中、已签收或已冻结的包裹均不满足）。全部满足时整单转为
2738	// “站间在途”（归属站点暂记源站），每件追加一条含运输单号、两站和时间的发运记录；
2739	// 成员按首次提交顺序保存，保存后不可修改。每件包裹同时最多属于一张未接收运输单。
2740	// 发运算新的流转：发运后不能退回此前的旧交接；运输单不是交接，不能作为退回的原交接。
2741	// 运输单号独立于已有各类编号，接收后也不释放：相同运输单号且源站、目的站、包裹集合
2742	// 相同（集合顺序无关），直接返回首次成员顺序与发运时间，replayed 为 true，不检查现状、
2743	// 不追加轨迹、不改写台账；运输单号相同但内容不同报冲突；失败的首次发运不占用运输单号。
2744	func (s *Store) Ship(shipment, from, to string, parcels []string, now time.Time) (res *ShipmentResult, replayed bool, err error) {
2745		if saved, ok := s.data.Shipments[shipment]; ok {
2746			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
2747				return saved, true, nil
2748			}
2749			return nil, false, fmt.Errorf("运输单号 %q 已用于一次不同的发运（源站=%q 目的站=%q），内容冲突", shipment, saved.From, saved.To)
2750		}
2751	
2752		// 首次发运：先做全部校验，任何一件不满足都整单拒绝。
2753		for _, id := range parcels {
2754			p, ok := s.data.Parcels[id]
2755			if !ok {
2756				return nil, false, fmt.Errorf("发运失败：包裹 %q 未登记，整单发运未执行", id)
2757			}
2758			if p.Station != from {
2759				return nil, false, fmt.Errorf("发运失败：包裹 %q 当前归属 %q，不在源站 %q，整单发运未执行", id, p.Station, from)
2760			}
2761			if p.Status != statusInStation {
2762				return nil, false, fmt.Errorf("发运失败：包裹 %q 当前状态为 %q，不是在站，整单发运未执行", id, p.Status)
2763			}
2764		}
2765	
2766		res = &ShipmentResult{
2767			Shipment: shipment,
2768			From:     from,
2769			To:       to,
2770			Parcels:  append([]string(nil), parcels...),
2771			Time:     now,
2772		}
2773		s.data.Shipments[shipment] = res
2774	
2775		// 记录旧值，落盘失败时整体回滚。
2776		prev := make(map[string]struct {
2777			status string
2778			trail  []Event
2779		}, len(parcels))
2780		for _, id := range parcels {
2781			p := s.data.Parcels[id]
2782			prev[id] = struct {
2783				status string
2784				trail  []Event
2785			}{p.Status, append([]Event(nil), p.Trail...)}
2786			p.Status = statusInTransit // 归属站点暂记源站，整单转为站间在途
2787			p.Trail = append(p.Trail, Event{
2788				Op:       "发运",
2789				Station:  from,
2790				From:     from,
2791				To:       to,
2792				Shipment: shipment,
2793				Time:     now,
2794			})
2795		}
2796	
2797		if err := s.save(); err != nil {
2798			delete(s.data.Shipments, shipment)
2799			for id, old := range prev {
2800				p := s.data.Parcels[id]
2801				p.Status = old.status
2802				p.Trail = old.trail
2803			}
2804			return nil, false, err
2805		}
2806		return res, false, nil
2807	}
