2809	// Receive 提交一次到站接收：运输单的部分或全部未到成员到达当前有效目的站。
2810	// parcels 为 nil 表示不选成员，接收当时全部尚未接收件；非 nil 为显式选择的
2811	// 非空、不重复集合（由调用方清洗）。
2812	//
2813	// 首次接收：运输单必须存在，接收站点必须等于运输单当前有效目的站（原目的站
2814	// 应用已有各次改址后），本次至少接收一件。显式集合的每件选中件都必须属于原单、
2815	// 尚未接收，且仍在源站归该单在途；不选成员时本次集合为当时的全部尚未接收件。
2816	// 任一不满足则整次拒绝，不作任何改动。
2817	// 已收件不再检查接收条件也不变更，其后续交接、冻结、配送或再次发运不妨碍余件接收。
2818	// 成功时按发运保存顺序将本次成员改归有效目的站、恢复“在站”，各追加一条含运输单号、
2819	// 两站、接收请求号和时间的接收记录；全部成员到齐后运输单永久标记为已接收，
2820	// 随后可继续在站作业。接收算新的流转：接收后不能退回此前的旧交接。
2821	// 两种选择方式共用接收请求号去重范围，与运输单号及已有各类编号独立，允许同名：
2822	// 相同接收请求号且运输单、接收站点、选择方式相同（显式集合换序无关），直接返回
2823	// 首次接收集合与时间，replayed 为 true，不检查现状、不重算余件、不追加轨迹、
2824	// 不改写台账（全部接收及后续流转后仍成立）；请求号相同但运输单、接收站点、
2825	// 选择方式或显式集合不同报冲突；全部接收后新请求拒绝；失败的首次接收不占用请求号。
2826	func (s *Store) Receive(request, shipment, station string, parcels []string, now time.Time) (res *ReceiveResult, replayed bool, err error) {
2827		explicit := parcels != nil
2828		if saved, ok := s.data.Receives[request]; ok {
2829			if saved.Shipment == shipment && saved.Station == station && saved.Explicit == explicit &&
2830				(!explicit || sameSet(saved.Parcels, parcels)) {
2831				return saved, true, nil
2832			}
2833			return nil, false, fmt.Errorf("接收请求号 %q 已用于一次不同的接收（运输单=%q 接收站点=%q），内容冲突",
2834				request, saved.Shipment, saved.Station)
2835		}
2836	
2837		sh, ok := s.data.Shipments[shipment]
2838		if !ok {
2839			return nil, false, fmt.Errorf("接收失败：运输单号 %q 不存在", shipment)
2840		}
2841		eff := s.effectiveTo(sh)
2842		if station != eff {
2843			return nil, false, fmt.Errorf("接收失败：接收站点 %q 不是运输单 %q 的当前有效目的站 %q，本次接收未执行", station, shipment, eff)
2844		}
2845	
2846		received := s.receivedUnder(shipment)
2847		var members []string // 本次接收集合，按发运保存顺序
2848		if explicit {
2849			if len(parcels) == 0 {
2850				return nil, false, fmt.Errorf("接收失败：显式选择的包裹集合不可为空，本次接收未执行")
2851			}
2852			want := make(map[string]bool, len(parcels))
2853			for _, pid := range parcels {
2854				want[pid] = true
2855			}
2856			// 先做全部校验：选中件均属原单、尚未接收且仍归该单在途，任一不符整次拒绝。
2857			for _, pid := range parcels {
2858				member := false
2859				for _, mid := range sh.Parcels {
2860					if mid == pid {
2861						member = true
2862						break
2863					}
2864				}
2865				if !member {
2866					return nil, false, fmt.Errorf("接收失败：包裹 %q 不属于运输单 %q，本次接收未执行", pid, shipment)
2867				}
2868				if received[pid] {
2869					return nil, false, fmt.Errorf("接收失败：包裹 %q 已在运输单 %q 下接收，不能重复接收，本次接收未执行", pid, shipment)
2870				}
2871				p := s.data.Parcels[pid] // 运输单成员必已登记（载入校验保证）
2872				if p.Status != statusInTransit || p.Station != sh.From {
2873					return nil, false, fmt.Errorf("接收失败：包裹 %q 当前归属 %q、状态 %q，不在运输单 %q 从源站 %q 在途，本次接收未执行",
2874						pid, p.Station, p.Status, shipment, sh.From)
2875				}
2876			}
2877			for _, mid := range sh.Parcels {
2878				if want[mid] {
2879					members = append(members, mid)
2880				}
2881			}
2882		} else {
2883			// 不选成员：本次集合为当时的全部尚未接收件，按发运保存顺序。
2884			for _, mid := range sh.Parcels {
2885				if !received[mid] {
2886					members = append(members, mid)
2887				}
2888			}
2889			if len(members) == 0 {
2890				return nil, false, fmt.Errorf("接收失败：运输单 %q 已全部接收（接收请求号 %q），没有尚未接收的成员，不能再次接收",
2891					shipment, sh.ReceivedBy)
2892			}
2893		}
2894	
2895		res = &ReceiveResult{
2896			Request:  request,
2897			Shipment: shipment,
2898			Station:  station,
2899			Parcels:  members,
2900			Time:     now,
2901			Explicit: explicit,
2902		}
2903		s.data.Receives[request] = res
2904		oldReceivedBy := sh.ReceivedBy
2905		if len(received)+len(members) == len(sh.Parcels) {
2906			sh.ReceivedBy = request // 全部成员到齐：运输单永久标记为已接收
2907		}
2908	
2909		// 记录旧值，落盘失败时整体回滚。
2910		prev := make(map[string]struct {
2911			station string
2912			status  string
2913			trail   []Event
2914		}, len(members))
2915		for _, pid := range members {
2916			p := s.data.Parcels[pid]
2917			prev[pid] = struct {
2918				station string
2919				status  string
2920				trail   []Event
2921			}{p.Station, p.Status, append([]Event(nil), p.Trail...)}
2922			p.Station = eff
2923			p.Status = statusInStation
2924			p.Trail = append(p.Trail, Event{
2925				Op:       "接收",
2926				Station:  eff,
2927				From:     sh.From,
2928				To:       eff,
2929				Shipment: shipment,
2930				Request:  request,
2931				Time:     now,
2932			})
2933		}
2934	
2935		if err := s.save(); err != nil {
2936			delete(s.data.Receives, request)
2937			sh.ReceivedBy = oldReceivedBy
2938			for pid, old := range prev {
2939				p := s.data.Parcels[pid]
2940				p.Station, p.Status = old.station, old.status
2941				p.Trail = old.trail
2942			}
2943			return nil, false, err
2944		}
2945		return res, false, nil
2946	}
2947	
2948	// Reroute 提交一次运输途中改址：将一张运输单当前全部未收件改送另一目的站，
2949	// 不另建运输单、不重新发运。成员取自受理时的全部未收件，不允许另选。
2950	//
2951	// 首次受理：运输单必须存在且仍有未收件；预期当前目的站必须等于当前有效目的站
2952	// （原目的站应用已有各次改址后）；新目的站必须不同于当前有效目的站和源站。
2953	// 本次集合为受理时的全部未收件，每件都必须仍归该单在源站站间在途，任一不符
2954	// 整次拒绝、不作任何改动。已收件不参与受理条件检查也不变更，其后续合法作业
