551	func cmdReceiptImport(dataFile string, argv []string, stdout, stderr io.Writer) int {
552		fs := newFlagSet("receipt-import", stderr)
553		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
554		file := fs.String("file", "", "回执导入文件路径（JSON 数组，只读，不会被修改）")
555		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptImportHelp); !ok {
556			return code
557		}
558	
559		if strings.TrimSpace(*file) == "" {
560			fmt.Fprintf(stderr, "%s receipt-import: 选项 --file 需要一个非空的回执导入文件路径\n", appName)
561			return exitBusiness
562		}
563	
564		// 输入文件只读；读取、解析或清洗失败时整份不予导入。
565		records, err := loadReceiptImportFile(*file)
566		if err != nil {
567			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
568			return exitBusiness
569		}
570	
571		store, release, err := OpenForUpdate(dataFile)
572		if err != nil {
573			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
574			return exitBusiness
575		}
576		defer release()
577		items, err := store.ImportReceipts(records, now())
578		if err != nil {
579			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
580			return exitBusiness
581		}
582	
583		replayed := 0
584		for _, it := range items {
585			if it.Replayed {
586				replayed++
587			}
588		}
589		fmt.Fprintf(stdout, "回执导入成功（共 %d 条：新增 %d 条，重放 %d 条）\n", len(items), len(items)-replayed, replayed)
590		for i, it := range items {
591			mark := "新增"
592			if it.Replayed {
593				mark = "重放（返回首次保存的结果）"
594			}
595			if it.Revoked {
596				mark += "，该回执已撤销"
597			}
598			line := fmt.Sprintf("  %d. 请求号: %s    批次号: %s    包裹编号: %s    结果: %s",
599				i+1, it.Record.Request, it.Record.Batch, it.Record.Parcel, it.Record.Result)
600			if it.Record.Result == resultFailed {
601				line += fmt.Sprintf("    原因: %s", it.Record.Reason)
602			}
603			fmt.Fprintf(stdout, "%s    标记: %s    时间: %s\n", line, mark, it.Time.Format(timeFmt))
604		}
605		return exitOK
606	}
