718			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
719			return exitBusiness
720		}
721		b, err := store.BatchQuery(cleanIDVal)
722		if err != nil {
723			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
724			return exitBusiness
725		}
726	
727		// 批次状态优先级：已中止 > 已永久转交 > 已完成 > 配送中。分批续接期间原批次
728		// 仍有待配送件时为配送中；余件全部经回执办结（无待配送件）时为已完成；
729		// 续接转走最后一件待配送件时永久关闭为已转交。
730		ab := store.BatchAbort(cleanIDVal)
731		closedTr := store.BatchTransferSource(cleanIDVal)
732		allTransfers := store.BatchTransfers(cleanIDVal)
733		status := "配送中"
734		switch {
735		case ab != nil:
736			status = "已中止"
737		case closedTr != nil:
738			status = "已转交"
739		case len(store.batchOpen(b)) == 0:
740			status = "已完成"
741		}
742		timeLabel := "出站时间"
743		if b.RelayedFrom != "" {
744			timeLabel = "接手时间"
745		}
746		fmt.Fprintf(stdout, "批次号: %s\n出发站: %s\n配送员: %s\n%s: %s\n批次状态: %s\n",
747			b.Batch, b.Station, b.Courier, timeLabel, b.Time.Format(timeFmt), status)
748		if b.RelayedFrom != "" {
749			src := store.TransferOf(b.RelayRequest)
750			fmt.Fprintf(stdout, "批次来源: 续接自批次 %s（原配送员: %s，续接请求号: %s）\n",
751				b.RelayedFrom, src.FromCourier, b.RelayRequest)
752		}
753		if ab != nil {
754			fmt.Fprintf(stdout, "中止请求号: %s\n中止原因: %s\n中止时间: %s\n",
755				ab.Request, ab.Reason, ab.Time.Format(timeFmt))
756		}
757		if closedTr != nil {
758			fmt.Fprintf(stdout, "转交去向: 批次 %s（新配送员: %s）\n续接请求号: %s\n续接原因: %s\n转交时间: %s\n",
759				closedTr.ToBatch, closedTr.ToCourier, closedTr.Request, closedTr.Reason, closedTr.Time.Format(timeFmt))
760		}
761		fmt.Fprintf(stdout, "逐件回执（%d/%d 已回执）:\n", b.Effective(), len(b.Parcels))
762		for _, pid := range b.Parcels {
763			e, ok := b.Receipts[pid]
764			if !ok || e.RevokedBy != "" {
765				switch {
766				case store.transferOfParcel(cleanIDVal, pid) != nil:
767					tr := store.transferOfParcel(cleanIDVal, pid)
768					fmt.Fprintf(stdout, "  - %s    已转交    去向批次: %s    新配送员: %s    续接请求号: %s    时间: %s\n",
769						pid, tr.ToBatch, tr.ToCourier, tr.Request, tr.Time.Format(timeFmt))
770				case ab != nil:
771					fmt.Fprintf(stdout, "  - %s    已收回    中止请求号: %s    原因: %s    时间: %s\n",
772						pid, ab.Request, ab.Reason, ab.Time.Format(timeFmt))
773				case ok:
774					fmt.Fprintf(stdout, "  - %s    未回执（原回执 %s 已撤销，撤销请求号: %s）\n", pid, e.Request, e.RevokedBy)
775				default:
776					fmt.Fprintf(stdout, "  - %s    未回执\n", pid)
777				}
778				continue
779			}
780			if e.Result == resultFailed {
781				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    原因: %s    请求号: %s    时间: %s\n",
782					pid, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
783			} else {
784				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    请求号: %s    时间: %s",
785					pid, e.Result, e.Request, e.Time.Format(timeFmt))
786				if e.ReturnedBy != "" {
787					if rr := store.ReceiptReturnOf(e.ReturnedBy); rr != nil {
788						fmt.Fprintf(stdout, "    已退件（实物送回 %s）    退件请求号: %s    时间: %s\n",
789							rr.Station, rr.Request, rr.Time.Format(timeFmt))
790					} else {
791						fmt.Fprintln(stdout)
792					}
793				} else {
794					fmt.Fprintln(stdout)
795				}
796			}
797		}
798		if len(allTransfers) > 0 {
799			fmt.Fprintf(stdout, "转交记录（%d 次，按提交顺序；转交不计回执）:\n", len(allTransfers))
800			for i, tr := range allTransfers {
801				fmt.Fprintf(stdout, "  %d. 续接请求号: %s    去向批次: %s    新配送员: %s    原因: %s    时间: %s    本次集合（%d 件）:\n",
802					i+1, tr.Request, tr.ToBatch, tr.ToCourier, tr.Reason, tr.Time.Format(timeFmt), len(tr.Parcels))
803				for _, pid := range tr.Parcels {
804					fmt.Fprintf(stdout, "      - %s\n", pid)
805				}
806			}
807		}
808		if rvs := store.BatchRevokes(cleanIDVal); len(rvs) > 0 {
809			fmt.Fprintf(stdout, "撤销记录（%d 条）:\n", len(rvs))
810			for _, rv := range rvs {
811				fmt.Fprintf(stdout, "  - 撤销请求号: %s    原回执请求号: %s    包裹: %s    批次: %s    原因: %s    时间: %s\n",
812					rv.Request, rv.Receipt, rv.Parcel, rv.Batch, rv.Reason, rv.Time.Format(timeFmt))
813			}
814		}
815		if rrs := store.BatchReceiptReturns(cleanIDVal); len(rrs) > 0 {
816			fmt.Fprintf(stdout, "退件记录（%d 条；退件不改变批次状态与回执进度，不算待配送或撤销）:\n", len(rrs))
817			for _, rr := range rrs {
818				fmt.Fprintf(stdout, "  - 退件请求号: %s    原签收请求号: %s    包裹: %s    批次: %s    接收站: %s    原因: %s    时间: %s\n",
819					rr.Request, rr.Receipt, rr.Parcel, rr.Batch, rr.Station, rr.Reason, rr.Time.Format(timeFmt))
820			}
821		}
822		return exitOK
823	}
