func cmdManifest(dataFile string, argv []string, stdout, stderr io.Writer) int {
	fs := newFlagSet("manifest", stderr)
	fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
	id := fs.String("id", "", "要查询的清单号")
	if ok, code := parseFlags(fs, argv, stdout, stderr, printManifestHelp); !ok {
		return code
	}

	cleanIDVal, err := cleanID("清单号", *id)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest: %v\n", appName, err)
		return exitBusiness
	}

	store, err := Open(dataFile)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest: %v\n", appName, err)
		return exitBusiness
	}
	m, err := store.ManifestQuery(cleanIDVal)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest: %v\n", appName, err)
		return exitBusiness
	}

	status := "待出站"
	if m.ConfirmedBatch != "" {
		status = "已出站"
	} else if m.CancelledBy != "" {
		status = "已取消"
	}
	fmt.Fprintf(stdout, "清单号: %s\n站点: %s\n清单状态: %s\n创建时间: %s\n成员（%d 件）:\n",
		m.Manifest, m.Station, status, m.Time.Format(timeFmt), len(m.Parcels))
	for _, pid := range m.Parcels {
		p, qerr := store.Query(pid)
		if qerr != nil {
			fmt.Fprintf(stdout, "  - %s\n", pid)
			continue
		}
		fmt.Fprintf(stdout, "  - %s    当前站点: %s    当前状态: %s\n", pid, p.Station, p.Status)
	}
	if m.ConfirmedBatch != "" {
		if b, berr := store.BatchQuery(m.ConfirmedBatch); berr == nil {
			fmt.Fprintf(stdout, "确认批次: %s    配送员: %s    出站时间: %s\n",
				b.Batch, b.Courier, b.Time.Format(timeFmt))
		}
	}
	if m.CancelledBy != "" {
		if c := store.ManifestCancelOf(m.CancelledBy); c != nil {
			fmt.Fprintf(stdout, "取消请求号: %s\n取消原因: %s\n取消时间: %s\n",
				c.Request, c.Reason, c.Time.Format(timeFmt))
		}
	}
	return exitOK
}

