		fmt.Fprintf(stdout, "接收请求号: %s\n接收站点: %s\n接收时间: %s\n",
			rv.Request, rv.Station, rv.Time.Format(timeFmt))
	}
	return exitOK
}

func cmdManifestCreate(dataFile string, argv []string, stdout, stderr io.Writer) int {
	fs := newFlagSet("manifest-create", stderr)
	fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
	manifest := fs.String("manifest", "", "清单号（独立去重，终结后也不能复用）")
	station := fs.String("station", "", "清单站点")
	var parcels stringList
	fs.Var(&parcels, "parcel", "包裹编号，可重复指定；集合不可为空或含重复编号")
	if ok, code := parseFlags(fs, argv, stdout, stderr, printManifestCreateHelp); !ok {
		return code
	}

	cleanManifest, err := cleanID("清单号", *manifest)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest-create: %v\n", appName, err)
		return exitBusiness
	}
	cleanStation, err := cleanID("清单站点", *station)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest-create: %v\n", appName, err)
		return exitBusiness
	}
	cleanParcels, err := cleanParcelList(parcels)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest-create: %v\n", appName, err)
		return exitBusiness
	}

	store, release, err := OpenForUpdate(dataFile)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest-create: %v\n", appName, err)
		return exitBusiness
	}
	defer release()
	result, replayed, err := store.CreateManifest(cleanManifest, cleanStation, cleanParcels, now())
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest-create: %v\n", appName, err)
		return exitBusiness
	}

	headline := "清单创建成功（整单预留）"
	if replayed {
		headline = "清单创建成功（清单号重复提交，返回首次保存的结果，未再追加轨迹）"
	}
	fmt.Fprintf(stdout, "%s\n清单号: %s\n站点: %s\n包裹（%d 件）:\n",
		headline, result.Manifest, result.Station, len(result.Parcels))
	for _, id := range result.Parcels {
		fmt.Fprintf(stdout, "  - %s\n", id)
	}
	fmt.Fprintf(stdout, "创建时间: %s\n", result.Time.Format(timeFmt))
	return exitOK
}

func cmdManifestConfirm(dataFile string, argv []string, stdout, stderr io.Writer) int {
	fs := newFlagSet("manifest-confirm", stderr)
	fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
