func cmdManifestCancel(dataFile string, argv []string, stdout, stderr io.Writer) int {
	fs := newFlagSet("manifest-cancel", stderr)
	fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
	request := fs.String("request", "", "取消请求号（独立去重）")
	manifest := fs.String("manifest", "", "要取消的清单号")
	reason := fs.String("reason", "", "取消原因")
	if ok, code := parseFlags(fs, argv, stdout, stderr, printManifestCancelHelp); !ok {
		return code
	}

	cleanReq, err := cleanID("取消请求号", *request)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest-cancel: %v\n", appName, err)
		return exitBusiness
	}
	cleanManifest, err := cleanID("清单号", *manifest)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest-cancel: %v\n", appName, err)
		return exitBusiness
	}
	cleanReason, err := cleanID("取消原因", *reason)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest-cancel: %v\n", appName, err)
		return exitBusiness
	}

	store, release, err := OpenForUpdate(dataFile)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest-cancel: %v\n", appName, err)
		return exitBusiness
	}
	defer release()
	result, replayed, err := store.CancelManifest(cleanReq, cleanManifest, cleanReason, now())
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest-cancel: %v\n", appName, err)
		return exitBusiness
	}

	headline := "清单取消成功"
	if replayed {
		headline = "清单取消成功（取消请求号重复提交，返回首次保存的结果，未再追加轨迹）"
	}
	fmt.Fprintf(stdout, "%s\n取消请求号: %s\n清单号: %s\n站点: %s\n取消原因: %s\n释放包裹（%d 件）:\n",
		headline, result.Request, result.Manifest, result.Station, result.Reason, len(result.Parcels))
	for _, id := range result.Parcels {
		fmt.Fprintf(stdout, "  - %s\n", id)
	}
	fmt.Fprintf(stdout, "取消时间: %s\n", result.Time.Format(timeFmt))
	return exitOK
}

func cmdManifest(dataFile string, argv []string, stdout, stderr io.Writer) int {
	fs := newFlagSet("manifest", stderr)
	fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
	id := fs.String("id", "", "要查询的清单号")
	if ok, code := parseFlags(fs, argv, stdout, stderr, printManifestHelp); !ok {
		return code
	}

	cleanIDVal, err := cleanID("清单号", *id)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest: %v\n", appName, err)
		return exitBusiness
	}

	store, err := Open(dataFile)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest: %v\n", appName, err)
		return exitBusiness
	}
	m, err := store.ManifestQuery(cleanIDVal)
	if err != nil {
		fmt.Fprintf(stderr, "%s manifest: %v\n", appName, err)
		return exitBusiness
	}

	status := "待出站"
	if m.ConfirmedBatch != "" {
		status = "已出站"
	} else if m.CancelledBy != "" {
		status = "已取消"
	}
	fmt.Fprintf(stdout, "清单号: %s\n站点: %s\n清单状态: %s\n创建时间: %s\n成员（%d 件）:\n",
		m.Manifest, m.Station, status, m.Time.Format(timeFmt), len(m.Parcels))
	for _, pid := range m.Parcels {
		p, qerr := store.Query(pid)
		if qerr != nil {
			fmt.Fprintf(stdout, "  - %s\n", pid)
			continue
		}
		fmt.Fprintf(stdout, "  - %s    当前站点: %s    当前状态: %s\n", pid, p.Station, p.Status)
	}
	if m.ConfirmedBatch != "" {
		if b, berr := store.BatchQuery(m.ConfirmedBatch); berr == nil {
			fmt.Fprintf(stdout, "确认批次: %s    配送员: %s    出站时间: %s\n",
				b.Batch, b.Courier, b.Time.Format(timeFmt))
		}
	}
	if m.CancelledBy != "" {
		if c := store.ManifestCancelOf(m.CancelledBy); c != nil {
			fmt.Fprintf(stdout, "取消请求号: %s\n取消原因: %s\n取消时间: %s\n",
				c.Request, c.Reason, c.Time.Format(timeFmt))
		}
	}
	return exitOK
}

