	p, _ := s.Query("P001")
	if len(p.Trail) != 1 {
		t.Fatal("保存失败必须回滚轨迹")
	}
	if _, err := os.Stat(path); !os.IsNotExist(err) {
		t.Fatalf("保存失败不得留下数据文件或临时文件, stat err=%v", err)
	}
}

